<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class ModerationScan extends Model { protected $fillable=['product_id','product_image_id','seller_id','store_id','provider','provider_reference','status','detected_category','confidence','risk_level','reviewed_by','reviewed_at','decision','review_notes','failure_message']; protected $casts=['reviewed_at'=>'datetime','confidence'=>'float']; public function product(){return $this->belongsTo(Product::class);} public function image(){return $this->belongsTo(ProductImage::class,'product_image_id');} public function seller(){return $this->belongsTo(User::class,'seller_id');} public function store(){return $this->belongsTo(Store::class);} public function reviewer(){return $this->belongsTo(User::class,'reviewed_by');} }
